#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define N 4
#define SIZE 16

// For BFS / IDA* we use a simple Manhattan distance heuristic
int target[N][N];

// Goal positions for each tile (0 is blank)
int goal_row[SIZE], goal_col[SIZE];

// Directions: up, down, left, right
int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};

// Precompute goal positions
void init_goal() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int val = target[i][j];
            goal_row[val] = i;
            goal_col[val] = j;
        }
    }
}

// Manhattan distance heuristic
int manhattan(int board[N][N]) {
    int sum = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int val = board[i][j];
            if (val != 0) {
                sum += abs(i - goal_row[val]) + abs(j - goal_col[val]);
            }
        }
    }
    return sum;
}

// Check if board is goal
int is_goal(int board[N][N]) {
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (board[i][j] != target[i][j])
                return 0;
    return 1;
}

// Find blank position
void find_blank(int board[N][N], int *r, int *c) {
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (board[i][j] == 0) { *r = i; *c = j; return; }
}

// IDA* recursive search
int bound;
int search(int board[N][N], int g, int prev_move, int blank_r, int blank_c) {
    int h = manhattan(board);
    int f = g + h;
    if (f > bound) return f;
    if (is_goal(board)) return 0; // found solution

    int next_bound = INT_MAX;

    for (int dir = 0; dir < 4; dir++) {
        // Skip reverse move
        if ((dir == 0 && prev_move == 1) || (dir == 1 && prev_move == 0) ||
            (dir == 2 && prev_move == 3) || (dir == 3 && prev_move == 2))
            continue;

        int nr = blank_r + dr[dir];
        int nc = blank_c + dc[dir];
        if (nr < 0 || nr >= N || nc < 0 || nc >= N) continue;

        // Make move
        board[blank_r][blank_c] = board[nr][nc];
        board[nr][nc] = 0;

        int t = search(board, g + 1, dir, nr, nc);
        if (t == 0) return 0; // found

        if (t < next_bound) next_bound = t;

        // Undo move
        board[nr][nc] = board[blank_r][blank_c];
        board[blank_r][blank_c] = 0;
    }
    return next_bound;
}

int ida_star(int board[N][N]) {
    int blank_r, blank_c;
    find_blank(board, &blank_r, &blank_c);

    bound = manhattan(board);
    if (bound == 0) return 0; // already solved

    while (1) {
        int t = search(board, 0, -1, blank_r, blank_c);
        if (t == 0) return bound;
        if (t == INT_MAX) return -1; // unsolvable
        bound = t;
    }
}

// Check if puzzle is solvable (inversion count parity)
int solvable(int board[N][N]) {
    int arr[SIZE], k = 0;
    int blank_row_from_bottom;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            arr[k] = board[i][j];
            if (arr[k] == 0) blank_row_from_bottom = N - i;
            k++;
        }
    }
    int inv = 0;
    for (int i = 0; i < SIZE; i++) {
        if (arr[i] == 0) continue;
        for (int j = i + 1; j < SIZE; j++) {
            if (arr[j] == 0) continue;
            if (arr[i] > arr[j]) inv++;
        }
    }
    // For N=4, solvable if (blank row from bottom + inversions) is odd
    return ((blank_row_from_bottom + inv) & 1) == 0;
}

int main() {
    int board[N][N];

    // Read target configuration (first 4x4 block)
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            scanf("%d", &target[i][j]);

    // Read initial configuration (second 4x4 block)
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            scanf("%d", &board[i][j]);

    init_goal();

    if (!solvable(board)) {
        printf("-1\n");
        return 0;
    }

    int steps = ida_star(board);
    printf("%d\n", steps);

    return 0;
}

