// Target position for each tile (0-15), target[i] = {row, col} for tile i
int target_row[16], target_col[16];

// Manhattan distance heuristic
int manhattan(int board[16]) {
    int dist = 0;
    for (int i = 0; i < 16; i++) {
        int tile = board[i];
        if (tile != 0) {
            int r = i / 4, c = i % 4;
            int dr = r - target_row[tile];
            int dc = c - target_col[tile];
            if (dr < 0) dr = -dr;
            if (dc < 0) dc = -dc;
            dist += dr + dc;
        }
    }
    return dist;
}

// Direction: up, down, left, right (move the blank)
int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};
int opp[] = {1, 0, 3, 2}; // opposite direction

int limit;
int found;

// IDA* search
// board: current state
// g: current cost
// blank: position of blank
// prev_dir: previous direction (to avoid reversals)
int dfs(int board[16], int g, int blank, int prev_dir) {
    int h = manhattan(board);
    int f = g + h;
    if (f > limit) return f;
    if (h == 0) {
        found = 1;
        return g;
    }

    int min_next = 1000000;
    int r = blank / 4, c = blank % 4;

    for (int d = 0; d < 4; d++) {
        if (prev_dir != -1 && d == opp[prev_dir]) continue; // don't reverse
        int nr = r + dr[d];
        int nc = c + dc[d];
        if (nr < 0 || nr >= 4 || nc < 0 || nc >= 4) continue;

        int new_blank = nr * 4 + nc;
        int tile = board[new_blank];

        // Update heuristic incrementally
        int old_h = abs(nr - target_row[tile]) + abs(nc - target_col[tile]);
        int new_h = abs(r - target_row[tile]) + abs(c - target_col[tile]);

        // Move: swap blank and tile
        board[blank] = tile;
        board[new_blank] = 0;

        int result = dfs(board, g + 1, new_blank, d);

        // Undo move
        board[new_blank] = tile;
        board[blank] = 0;

        if (found) return result;
        if (result < min_next) min_next = result;
    }

    return min_next;
}

